<?php
declare(strict_types=1);
use App\Support\Html;
use App\Support\Language;
/** @var Language $lang */
/** @var list<App\Domain\Project> $projects */
?>
<section class="page-hero shell"><span class="eyebrow">INDEX / SOFTWARE & EXPERIMENTS</span><h1><?= $lang->value('Projekty.','Projects.') ?></h1><p><?= $lang->value('Vlastní software, infrastruktura, hry i technické experimenty. Soukromé projekty jsou popsané bez zveřejnění zdrojového kódu.', 'Original software, infrastructure, games and engineering experiments. Private work is described without exposing source code.') ?></p><div class="page-meta"><?= count($projects) ?> <?= $lang->value('PROJEKTOVÝCH STUDIÍ', 'PROJECT STUDIES') ?> <span>·</span> <?= $lang->value('VEŘEJNÉ + SOUKROMÉ PŘÍPADOVÉ STUDIE', 'PUBLIC + PRIVATE CASE STUDIES') ?></div></section>
<section class="section shell" data-project-browser><div class="filter-bar"><label class="search-field"><span class="visually-hidden"><?= $lang->value('Hledat projekt','Search projects') ?></span><span aria-hidden="true">⌕</span><input type="search" placeholder="<?= $lang->value('Hledat podle názvu nebo technologie…','Find a name or technology…') ?>" data-search autocomplete="off"></label><select data-filter aria-label="Category"><option value="all"><?= $lang->value('Všechny kategorie','All categories') ?></option><?php foreach (array_unique(array_map(static fn ($p) => $p->category, $projects)) as $category): ?><option value="<?= Html::escape(strtolower($category)) ?>"><?= Html::escape($category) ?></option><?php endforeach; ?></select><span class="filter-count" data-count><?= count($projects) ?> <?= $lang->value('projektů', 'projects') ?></span></div>
<div class="project-grid" data-results>
<?php foreach ($projects as $i => $project): ?><a class="project-card" data-project data-category="<?= Html::escape(strtolower($project->category)) ?>" data-search-text="<?= Html::escape(strtolower($project->name.' '.implode(' ', $project->stack).' '.$project->category.' '.$project->summary($lang))) ?>" href="<?= $lang->path('/projects/'.$project->slug) ?>"><div class="project-card-top"><span class="project-glyph" aria-hidden="true"><?= str_pad((string)($i+1),2,'0',STR_PAD_LEFT) ?></span><span class="status <?= Html::escape($project->status) ?>"><?= Html::escape($project->status) ?></span></div><span class="category"><?= Html::escape($project->category) ?></span><h3><?= Html::escape($project->name) ?></h3><p><?= Html::escape($project->summary($lang)) ?></p><div class="stack-list"><?php foreach (array_slice($project->stack,0,4) as $tag): ?><span><?= Html::escape($tag) ?></span><?php endforeach; ?></div><span class="card-action"><?= $project->private ? 'PRIVATE STUDY' : 'OPEN SOURCE' ?> ↗</span></a><?php endforeach; ?>
</div><p class="empty-state hidden" data-empty><?= $lang->value('Žádný projekt neodpovídá filtru.','No projects match the filter.') ?></p></section>
